import { model, Schema } from "mongoose";
import {
  MEDICINE_LIMITS,
  MedicineAdministrationRoutes,
  MedicineCategories,
  MedicineDosageForms,
} from "./medicine.constants.js";
import type { TMedicine } from "./medicine.interface.js";

const medicineSchema = new Schema<TMedicine>(
  {
    //generated by generateMedicineCode (MED-00001) and never accepted from the client
    medicineCode: {
      type: String,
      required: true,
      unique: true,
      immutable: true,
      trim: true,
      uppercase: true,
    },
    medicineName: { type: String, required: true, trim: true, maxlength: 150 },
    genericName: { type: String, required: true, trim: true, maxlength: 150 },
    brandName: { type: String, trim: true, maxlength: 150 },
    manufacturer: { type: String, required: true, trim: true, maxlength: 150 },
    category: { type: String, enum: Object.values(MedicineCategories), required: true },
    dosageForm: { type: String, enum: Object.values(MedicineDosageForms), required: true },
    strength: { type: String, required: true, trim: true, maxlength: 60 },
    administrationRoute: {
      type: String,
      enum: Object.values(MedicineAdministrationRoutes),
      required: true,
    },
    description: { type: String, trim: true, maxlength: 2000 },
    storageCondition: { type: String, required: true, trim: true, maxlength: 200 },
    withdrawalPeriodDays: {
      type: Number,
      required: true,
      min: [0, "withdrawalPeriodDays cannot be negative"],
      max: MEDICINE_LIMITS.maxWithdrawalPeriodDays,
    },
    prescriptionRequired: { type: Boolean, required: true, default: false },
    //retired instead of deleted so Treatment / Inventory references never break
    isActive: { type: Boolean, required: true, default: true },
  },
  { timestamps: true },
);

//search / filter indexes (spec §79). Product-identity duplicates are detected in the
//service with normalized text, so there is no unique compound index here.
medicineSchema.index({ medicineName: 1 });
medicineSchema.index({ genericName: 1 });
medicineSchema.index({ brandName: 1 });
medicineSchema.index({ manufacturer: 1 });
medicineSchema.index({ isActive: 1, category: 1 });
medicineSchema.index({ prescriptionRequired: 1, isActive: 1 });
medicineSchema.index({ dosageForm: 1 });

export const MedicineModel = model<TMedicine>("Medicine", medicineSchema);
